INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8301, '1 Kings 3:22', '1 Kings', 3, 22, '&nbsp;خو هغه بلې ښځې ووئيل، ”نه، ژوندے ماشوم زما دے او دا مړ ماشوم ستا دے.“ نو هغه وړومبۍ ښځې جواب ورکړو، ”نه، مړ ماشوم ستا دے او ژوندے ماشوم زما دے.“ نو داسې هغوئ د بادشاه په وړاندې بحث شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8302, '1 Kings 3:23', '1 Kings', 3, 23, '&nbsp;نو سليمان بادشاه وفرمائيل، ”تاسو دواړه دا دعوىٰ کوئ چې ژوندے ماشوم زما دے او مړ ماشوم زما نۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8303, '1 Kings 3:24', '1 Kings', 3, 24, '&nbsp;نو هغۀ وفرمائيل چې تُوره راوړه او چې کله تُوره راوړے شوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8304, '1 Kings 3:25', '1 Kings', 3, 25, '&nbsp;نو هغۀ وفرمائيل، ”دا ژوندے ماشوم دوه ټوټې کړه او هرې يوې له نيم نيم ورکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8305, '1 Kings 3:26', '1 Kings', 3, 26, '&nbsp;د کومې مور چې زوئ ژوندے وو او زړۀ يې د زوئ د مينې نه ډک وو، نو هغې بادشاه ته ووئيل، ”بادشاه سلامت، دا ماشوم مۀ وژنه او هغې له يې ورکړه.“ خو هغې بلې ښځې ووئيل، ”دا ماشوم مونږ يوې له هم مۀ راکوه او دوه ټوټې يې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8306, '1 Kings 3:27', '1 Kings', 3, 27, '&nbsp;سليمان وفرمائيل، ”ماشوم مۀ وژنه. او هغه ښځې له يې ورکړه چې کومه وائى چې مۀ يې وژنه. هغه يې اصلى مور ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8307, '1 Kings 3:28', '1 Kings', 3, 28, '&nbsp;کله چې ټول بنى اِسرائيليان د سليمان د فېصلې نه خبر شول، نو د هغۀ رُعب ورباندې پرېوتو، ځکه چې هغوئ ته نوره پته ولګېده چې خُدائ پاک هغۀ له حِکمت ورکړے دے چې په اِنصاف سره لانجې هوارې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8308, '1 Kings 4:1', '1 Kings', 4, 1, '&nbsp;سليمان د ټولو بنى اِسرائيلو بادشاه وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8309, '1 Kings 4:2', '1 Kings', 4, 2, '&nbsp;او دا کسان د هغۀ لوئ آفسران وُو، د صدوق زوئ عزرياه اِمام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8310, '1 Kings 4:3', '1 Kings', 4, 3, '&nbsp;د دربار منشيان، د سيسه زامن اليحورف او اخياه، تاريخ ليکونکى، د اخيلود زوئ يهوسفط،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8311, '1 Kings 4:4', '1 Kings', 4, 4, '&nbsp;د لښکر مشر، د يهويدع زوئ بناياه، اِمامان، صدوق او ابياتار،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8312, '1 Kings 4:5', '1 Kings', 4, 5, '&nbsp;د ضِلعې د حکمرانانو مشر، د ناتن زوئ عزرياه، شاهى مشير، د ناتن زوئ زبود اِمام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8313, '1 Kings 4:6', '1 Kings', 4, 6, '&nbsp;د محل مشر، اخيسر، د هغه مزدورانو مشر چې په زور کار ترې نه اخستے شو، د عبدا زوئ ادونرام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8314, '1 Kings 4:7', '1 Kings', 4, 7, '&nbsp;سليمان د بنى اِسرائيلو په مُلک کښې دولس سړى د ضِلعې حکمران مقرر کړل. هغوئ د بادشاه او د هغۀ د خاندان او درباريانو دپاره د خوراک بندوبست کولو. هر يو سړے په کال کښې د يوې مياشتې ذمه وار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8315, '1 Kings 4:8', '1 Kings', 4, 8, '&nbsp;دا د هغه دولسو آفسرانو او د هغه ضِلعو نومونه دى چې هغوئ د کومو آفسران وُو. بِن‌حُور، د اِفرائيم د غرونو مُلک،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8316, '1 Kings 4:9', '1 Kings', 4, 9, '&nbsp;بِن‌دِقر، مقص، سعلبيم، بيت‌شمس، ايلون، او بيت‌حنان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8317, '1 Kings 4:10', '1 Kings', 4, 10, '&nbsp;بِن‌حصد، د اربوت او شوکه ښارونو او د حِفر د ټولې علاقې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8318, '1 Kings 4:11', '1 Kings', 4, 11, '&nbsp;بِن‌ابينداب چا چې د سليمان لور طافت وادۀ کړې وه، د دور د ټولې علاقې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8319, '1 Kings 4:12', '1 Kings', 4, 12, '&nbsp;د اخيلود زوئ بعنه، د تعنک او مِجدو د ښارونو او بيت‌شان ته نزدې د ټولې علاقې، ضرتان ښار ته نزدې، د يزرعيل ښار جنوبى برخه او د ابيل‌محوله او يقمعام ښار پورې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8320, '1 Kings 4:13', '1 Kings', 4, 13, '&nbsp;بِن‌جبر، په رامات‌جِلعاد کښې د هغه کلو چې د يائير د قبيلې وُو، يائير د منسى اولاد وو، په بسن کښې د ارجوب علاقه، چې ټول شپېتۀ لوئ ښارونه وُو، چې پاخۀ دېوالونه او په دروازو کښې يې د زېړو سيخونه لرل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8321, '1 Kings 4:14', '1 Kings', 4, 14, '&nbsp;د عدو زوئ اخينداب، د محنايم د علاقې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8322, '1 Kings 4:15', '1 Kings', 4, 15, '&nbsp;اخيمعض، چا چې د سليمان يوه بله لور باسمت وادۀ کړې وه، د نفتالى علاقې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8323, '1 Kings 4:16', '1 Kings', 4, 16, '&nbsp;د حوسى زوئ بعنه، د آشر علاقه او د بعلوت ښار،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8324, '1 Kings 4:17', '1 Kings', 4, 17, '&nbsp;د فروح زوئ يهوسفط، د يساکار علاقه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8325, '1 Kings 4:18', '1 Kings', 4, 18, '&nbsp;د ايله زوئ سِمعى، د بنيامين علاقه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8326, '1 Kings 4:19', '1 Kings', 4, 19, '&nbsp;د اورى زوئ جابر، د جِلعاد علاقه چې په دې باندې امورى بادشاه سيحون او د بسن بادشاه عوج بادشاهى کړې وه. د دې دولسو نه علاوه په دې ټول مُلک باندې يو حکمران وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8327, '1 Kings 4:20', '1 Kings', 4, 20, '&nbsp;د يهوداه او د اِسرائيل خلق د سمندر په غاړه د شګو په شان بې‌شمېره وُو، هغوئ خوراک څښاک کولو او خوشحاله وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8328, '1 Kings 4:21', '1 Kings', 4, 21, '&nbsp;د سليمان په بادشاهۍ کښې د فرات سيند نه واخله تر فلستيانو مُلک او د مِصر د حد پولې پورې ټول قومونه شامل وُو. هغوئ به هغۀ له محصُول ورکولو او چې ترڅو ژوندے وُو نو د هغۀ خِدمت يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8329, '1 Kings 4:22', '1 Kings', 4, 22, '&nbsp;هغوئ سليمان له هره ورځ تقريباً پينځۀ زره کلو د ښو اوړو او لس زره کېلو مېده بندوبست کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8330, '1 Kings 4:23', '1 Kings', 4, 23, '&nbsp;لس په غله باندې ساتلى څاروى، شل په څرېدو ساتلى څاروى او سل ګډې، چې ورسره هوسۍ، باره سينګۍ، غرڅۍ او څاربۀ چرګان هم وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8331, '1 Kings 4:24', '1 Kings', 4, 24, '&nbsp;سليمان د فرات سيند نمرپرېواتۀ طرف ته د تِفسَح نه واخله د غزه ښار پورې په ټول مُلک بادشاهى کوله. او هغه د خپلو ټولو ګاونډى مُلکونو سره په امن کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8332, '1 Kings 4:25', '1 Kings', 4, 25, '&nbsp;چې تر کومې پورې هغه ژوندے وو نو د يهوداه او د اِسرائيل خلق په امن سره اوسېدل، هر خاندان د انګورو باغونه او د اينځرو ونې لرلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8333, '1 Kings 4:26', '1 Kings', 4, 26, '&nbsp;سليمان د خپلو جنګى ګاډو د آسونو دپاره څلوېښت زره اخورونه لرل او د خپلو فوجيانو دپاره يې دولس زره آسونه لرل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8334, '1 Kings 4:27', '1 Kings', 4, 27, '&nbsp;هغه دولسو حکمرانانو به هر يو په خپله خپله مياشت کښې سليمان بادشاه او د هغۀ ټولو دپاره د خوراک بندوبست کولو چې چا د هغۀ د دسترخوان نه خوراک کولو، هغوئ به د هر څيز داسې بندوبست کولو چې د يو څيز کمے به هم نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8335, '1 Kings 4:28', '1 Kings', 4, 28, '&nbsp;هر يو حکمران خپله برخه اوربشې او بوس هم هلته لېږل چرته چې ضرورت وو، دا د جنګى ګاډو د آسونو او د نورو آسونو دپاره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8336, '1 Kings 4:29', '1 Kings', 4, 29, '&nbsp;خُدائ پاک سليمان له لوئ حِکمت، عقل او دومره پوهه ورکړې وه چې د حِساب نه بهر وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8337, '1 Kings 4:30', '1 Kings', 4, 30, '&nbsp;سليمان د نمرخاتۀ د ټولو هوښيارانو او د مِصر د هوښيارو سړو نه زيات هوښيار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8338, '1 Kings 4:31', '1 Kings', 4, 31, '&nbsp;هغه د ټولو خلقو نه زيات هوښيار وو، هغه د ازراحى ايتان، د محول د زامنو هيمان، کل‌کُول او دردع نه زيات هوښيار وو او د هغۀ مشهورتيا په ګېرچاپېره ټولو مُلکونو کښې خوره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8339, '1 Kings 4:32', '1 Kings', 4, 32, '&nbsp;هغۀ درې زره متلونه او يو زر او پينځۀ سندرې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8340, '1 Kings 4:33', '1 Kings', 4, 33, '&nbsp;هغۀ د ونو او بوټو په حقله خبرې کولې، د لبنان د دِيار نه واخله تر ويلنى پورې چې په دېوالونو باندې کيږى، هغۀ د ځناورو، مارغانو، په خېټه ښوئېدونکو څيزونو او کبانو په حقله خبرې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8341, '1 Kings 4:34', '1 Kings', 4, 34, '&nbsp;د ټولې دُنيا بادشاهان د سليمان د حِکمت نه خبر شول او خلق يې ورلېږل چې د هغۀ خبرې واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8342, '1 Kings 5:1', '1 Kings', 5, 1, '&nbsp;د صور بادشاه حيرام د داؤد همېشه ملګرے وو او چې کله هغه خبر شو چې سليمان د خپل پلار داؤد نه پس بادشاه جوړ شوے دے نو هغۀ له يې سفيران ورولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8343, '1 Kings 5:2', '1 Kings', 5, 2, '&nbsp;سليمان حيرام ته دا پېغام ولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8344, '1 Kings 5:3', '1 Kings', 5, 3, '&nbsp;”تا ته پته ده چې زما پلار داؤد هر وخت د هغه ګېرچاپېره مُلکونو د دشمنانو سره جنګونه کول نو په دې وجه هغۀ د مالِک خُدائ د هغۀ خُدائ پاک دپاره يو کور تر هغې پورې نۀ شو جوړولے چې مالِک خُدائ هغۀ له په خپلو دشمنانو باندې فتح نۀ وه ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8345, '1 Kings 5:4', '1 Kings', 5, 4, '&nbsp;خو اوس مالِک خُدائ زما خُدائ پاک زما ټول سرحدونه په امن کښې کړى دى. نۀ زما دشمنان شته او نۀ د حملې څۀ خطره شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8346, '1 Kings 5:5', '1 Kings', 5, 5, '&nbsp;مالِک خُدائ زما د پلار داؤد سره وعده کړې وه چې ستا زوئ، کوم چې ستا نه پس بادشاه جوړوم، هغه به زما دپاره يو کور جوړ کړى. او اوس ما دا فېصله کړې ده چې د مالِک خُدائ زما د خُدائ پاک د عبادت دپاره به هغه کور جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8347, '1 Kings 5:6', '1 Kings', 5, 6, '&nbsp;نو خپل سړى لبنان ته ولېږه چې زما دپاره د دِيار ونې ووهى. زما سړى به د هغوئ سره کار کوى او چې تۀ څۀ فېصله وکړې نو زۀ به ستا سړو له هم هغه هومره مزدورى ورکوم. لکه چې تا ته ښۀ پته ده چې په مونږ کښې د صيدانيانو په شان د لرګو پرې کولو والا تکړه کسان نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8348, '1 Kings 5:7', '1 Kings', 5, 7, '&nbsp;حيرام ته چې کله د سليمان پېغام مِلاو شو نو ډېر زيات خوشحاله شو او هغۀ ووئيل، ”د مالِک خُدائ ثناء صِفت دې وى چې هغۀ نن داؤد له يو هوښيار زوئ ورکړے دے چې د هغۀ په ځائ د دې عظيم قوم بادشاه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8349, '1 Kings 5:8', '1 Kings', 5, 8, '&nbsp;بيا حيرام سليمان له دا پېغام ولېږلو، ”ما ته ستا پېغام مِلاو شوے دے او چې څۀ دې فرمائيلى دى د هغې کولو ته تيار يم. زۀ به د دِيار او د نختر د ونو بندوبست وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8350, '1 Kings 5:9', '1 Kings', 5, 9, '&nbsp;زما سړى به لرګى د لبنان نه سمندر ته راوړى او هغوئ به دا د يو بل سره د کشتۍ په شان وتړى او چې کوم ځائ تاسو خوښ کړئ نو هغه ځائ ته به يې په اوبو کښې ورسوى. زما سړى به دا هلته کولاو کړى او ستا سړو ته به يې حواله کړى. او تاسو له په کار دى چې زما د محل خلقو له د خوراک بندوبست وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8351, '1 Kings 5:10', '1 Kings', 5, 10, '&nbsp;نو حيرام سليمان له د هغه ټولو د دِيار او د نختر د لرګو بندوبست وکړو چې هغۀ غوښتى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8352, '1 Kings 5:11', '1 Kings', 5, 11, '&nbsp;او سليمان حيرام له دوه زره ټنه غنم او څلور لاکه کلو سوچه د زيتُونو تېل ورکړل نو د هغۀ د محل د خلقو د هر کال د خوراک بندوبست وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8353, '1 Kings 5:12', '1 Kings', 5, 12, '&nbsp;مالِک خُدائ خپله وعده پوره کړه او سليمان له يې حِکمت ورکړو. او د حيرام او سليمان په مينځ کښې امن شو او د يو بل سره يې تړون وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8354, '1 Kings 5:13', '1 Kings', 5, 13, '&nbsp;سليمان د ټولو بنى اِسرائيلو نه دېرش زره مزدوران راغونډ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8355, '1 Kings 5:14', '1 Kings', 5, 14, '&nbsp;او ادونرام يې د هغوئ مشر مقرر کړو. هغۀ هغوئ د لسو زرو په درې قبيلو کښې تقسيم کړل او هرې قبيلې به يوه مياشت په لبنان کښې او دوه مياشتې په کور کښې تېرولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8356, '1 Kings 5:15', '1 Kings', 5, 15, '&nbsp;سليمان د غرونو په مُلک کښې اتيا زره سړى لرل چې کاڼى يې راويستل او اويا زره سړو دا راوړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8357, '1 Kings 5:16', '1 Kings', 5, 16, '&nbsp;او هغۀ درې زره او درې سوه مشران مقرر کړل چې د هغوئ د کار مشرى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8358, '1 Kings 5:17', '1 Kings', 5, 17, '&nbsp;د سليمان د حُکم په مطابق هغوئ د مالِک خُدائ کور د بنياد دپاره ښائسته او لوئ کاڼى تيار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8359, '1 Kings 5:18', '1 Kings', 5, 18, '&nbsp;د سليمان او د حيرام سړو او د جبل د ښار سړو د خُدائ پاک کور د جوړولو دپاره کاڼى او لرګى تيار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8360, '1 Kings 6:1', '1 Kings', 6, 1, '&nbsp;د بنى اِسرائيلو د مِصر نه د راوتلو څلور سوه او اتيا کاله پس، په بنى اِسرائيلو باندې د سليمان د بادشاهۍ په څلورم کال، په دوېمه يعنې د زيو په مياشت کښې، سليمان د مالِک خُدائ په کور باندې کار شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8361, '1 Kings 6:2', '1 Kings', 6, 2, '&nbsp;دننه دا تقريباً دېرش ګزه اوږده، لس ګزه پلنه او پينځلس ګزه اوچته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
