(8363, '1 Kings 6:4', '1 Kings', 6, 4, '&nbsp;د هغه کور په دېوالونو باندې تنګې کړکۍ لګېدلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8364, '1 Kings 6:5', '1 Kings', 6, 5, '&nbsp;هغۀ د خُدائ پاک د کور په دوو طرفونو او شاته نورې کوټې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8365, '1 Kings 6:6', '1 Kings', 6, 6, '&nbsp;د دې کوټو درې درې منزلونه وُو. لاندينۍ کوټه تقريباً دوه نيمه ګزه پلنه، دوېمه کوټه درې ګزه پلنه او آخرى کوټه درې نيم ګزه پلنه وه. د مالِک خُدائ د کور په دېوالونو کښې سورى نۀ وُو جوړ کړے شوى، څۀ کاڼى بهر راوتى وُو چې د چت تيرونه ورباندې پراتۀ وُو او په دېوال کښې دننه نۀ لګېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8366, '1 Kings 6:7', '1 Kings', 6, 7, '&nbsp;د کومو کاڼو نه چې د مالِک خُدائ کور جوړ شوے وو هغه په کان کښې تيار شوى وُو، نو چې کله هغه کور جوړېدو، نو د څټکو، تېشو، يا د اوسپنو د نورو آوزارو آواز د خُدائ پاک په کور کښې نۀ وو اورېدلے شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8367, '1 Kings 6:8', '1 Kings', 6, 8, '&nbsp;د لاندينى منزل دروازه د مالِک خُدائ د کور جنوبى طرف ته وه، چې دوېم او درېم چت ته يې پوړۍ ختلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8368, '1 Kings 6:9', '1 Kings', 6, 9, '&nbsp;نو سليمان بادشاه د هغه کور جوړول ختم کړل. هغۀ ورله يو چت جوړ کړو چې د تيرونو او د دِيار د تختو نه جوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8369, '1 Kings 6:10', '1 Kings', 6, 10, '&nbsp;هغۀ د کور په درې طرفونو باندې کوټې جوړې کړې، چې د کور د دېوالونو سره د دِيار په تيرونو باندې مِلاو وې. هره يوه کوټه دوه نيمه ګزه اوچته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
