(8371, '1 Kings 6:12', '1 Kings', 6, 12, '&nbsp;”تۀ د مالِک خُدائ کور جوړوې نو ياد ساته چې زما په ټول قانون او حُکمونو باندې به عمل کوې، نو زۀ به ستا دپاره هغه څۀ وکړم چې ما ستا د پلار داؤد سره د هغې وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8372, '1 Kings 6:13', '1 Kings', 6, 13, '&nbsp;زۀ به د خپلو خلقو بنى اِسرائيلو سره په دې کور کښې اوسېږم او زۀ به هيڅکله هغوئ پرې نۀ ږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
