(8377, '1 Kings 6:18', '1 Kings', 6, 18, '&nbsp;د دِيار تختې د کدو او د ګلونو په ګُلکارۍ باندې ښائسته کړے شوې وې، دننه ټوله حِصه په دِيار پټه وه او د دېوال کاڼى نۀ ښکارېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
