(8396, '1 Kings 7:4', '1 Kings', 7, 4, '&nbsp;دواړو طرفونو ته په دېوالونو باندې درې قطاره کړکۍ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8397, '1 Kings 7:5', '1 Kings', 7, 5, '&nbsp;د دروازو او کړکو څلور ګوټه چوکاټونه وُو او په درې قطارونو کښې يو بل ته مخامخ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8398, '1 Kings 7:6', '1 Kings', 7, 6, '&nbsp;سليمان د ستنو يو دربار جوړ کړو، چې پينځۀ اويا فټه اوږد او پينځۀ څلوېښت فټه پلن وو. د دې مخامخ يوه د ستنو برانډه او مخې ته يې يو دالان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8399, '1 Kings 7:7', '1 Kings', 7, 7, '&nbsp;هغۀ د تخت کوټه هم جوړه کړه چې د اِنصاف دربار هم بللے شو، چرته چې سليمان لانجې هوارولې، چې د فرش نه تر سره پورې يې د دِيار تختې لرلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8400, '1 Kings 7:8', '1 Kings', 7, 8, '&nbsp;د اِنصاف د دربار نه وروستو په يو بل دربار کښې، د سليمان خپلې کوټې هم د نورو کوټو په شان وې. هغۀ د خپلې ښځې، د فِرعون د لور دپاره هم هغه شان کور جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');